using System;using System.IO;using System.Linq;using System.Security.Cryptography;using Mono.Cecil;using Mono.Cecil.Cil;
class PatchPaths {
 static string H(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static void Main(string[] a){if(Path.GetFullPath(a[0])==Path.GetFullPath(a[2]))throw new Exception("Refusing in-place write");bool texture=Path.GetFileName(a[0])=="TextureReplacer.dll";string expected=texture?"ce1cf6e8615eec950f5a393f203b921c675632f74f1be6bf2176b65378152377":"15320705ef8362e5ffdcaa0ed91a72982973d6fd113e52d09765079db15c65ba";if(H(a[0])!=expected)throw new Exception("Unknown input hash");var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(a[3]);resolver.AddSearchDirectory(Path.GetDirectoryName(a[0]));using(var x=AssemblyDefinition.ReadAssembly(a[0],new ReaderParameters{AssemblyResolver=resolver}))using(var helper=AssemblyDefinition.ReadAssembly(a[1])){var ht=helper.MainModule.GetType("TCG.NativeCompatibility.PathLiterals");int edits=0;if(texture){var t=x.MainModule.GetType("TextureReplacer.BepInExPlugin");var select=x.MainModule.ImportReference(ht.Methods.Single(m=>m.Name=="Select"));foreach(var m in t.Methods.Where(m=>m.Name=="CacheCardDataAtStart"||m.Name=="LoadCardNames")){var il=m.Body.GetILProcessor();foreach(var i in m.Body.Instructions.ToArray()){if(i.OpCode==OpCodes.Ldstr&&new[]{"\\cards","\\"}.Contains(i.Operand as string)){il.InsertAfter(i,Instruction.Create(OpCodes.Call,select));edits++;}}}if(edits!=5)throw new Exception("Expected5 texture path sites");}else{var m=x.MainModule.GetType("EnhancedPrefabLoader.Prepatch.PatchDataManager").Methods.Single(t=>t.Name==".cctor");var ins=m.Body.Instructions.Single(i=>i.Offset==12&&i.OpCode==OpCodes.Call&&((MethodReference)i.Operand).FullName=="System.String System.String::Concat(System.String,System.String)");ins.Operand=x.MainModule.ImportReference(ht.Methods.Single(t=>t.Name=="PrepatchDataBase"));edits++;}x.Write(a[2]+".tmp");if(File.Exists(a[2]))File.Delete(a[2]);File.Move(a[2]+".tmp",a[2]);Console.WriteLine("Staged "+Path.GetFileName(a[2])+" with "+edits+" platform dispatch sites");}}
